ALTER TABLE warehouses ADD UNIQUE(tenant_id,id);
CREATE TABLE suppliers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,code varchar(64) NOT NULL,name varchar(120) NOT NULL,phone varchar(30),address varchar(300),status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,code));
CREATE TABLE receipts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,site_id uuid NOT NULL,warehouse_id uuid NOT NULL,code text NOT NULL,source_type text NOT NULL CHECK(source_type IN ('PURCHASE','OPENING_STOCK')),supplier_id uuid,supplier_name text,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','POSTED','CANCELLED')),note varchar(500) NOT NULL DEFAULT '',total_vnd numeric(20,0) NOT NULL CHECK(total_vnd>=0),version integer NOT NULL DEFAULT 1,created_by text NOT NULL,posted_by text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),posted_at timestamptz,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),FOREIGN KEY(tenant_id,supplier_id) REFERENCES suppliers(tenant_id,id),CHECK((source_type='PURCHASE' AND supplier_id IS NOT NULL) OR (source_type='OPENING_STOCK' AND supplier_id IS NULL)));
CREATE TABLE receipt_lines(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,receipt_id uuid NOT NULL,position integer NOT NULL,sku_id uuid NOT NULL,unit_id uuid NOT NULL,sku_code text NOT NULL,sku_name text NOT NULL,unit_name text NOT NULL,base_unit text NOT NULL,factor numeric(18,3) NOT NULL CHECK(factor>0),qty numeric(18,3) NOT NULL CHECK(qty>0),qty_base numeric(18,3) NOT NULL CHECK(qty_base>0),unit_cost_vnd numeric(20,0) NOT NULL CHECK(unit_cost_vnd>=0),total_vnd numeric(20,0) NOT NULL CHECK(total_vnd>=0),UNIQUE(tenant_id,receipt_id,sku_id),FOREIGN KEY(tenant_id,receipt_id) REFERENCES receipts(tenant_id,id));
CREATE TABLE stock_balances(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,warehouse_id uuid NOT NULL,sku_id uuid NOT NULL,on_hand numeric(18,3) NOT NULL DEFAULT 0 CHECK(on_hand>=0),reserved numeric(18,3) NOT NULL DEFAULT 0 CHECK(reserved>=0),quarantined numeric(18,3) NOT NULL DEFAULT 0 CHECK(quarantined>=0),inventory_value numeric(20,0) NOT NULL DEFAULT 0 CHECK(inventory_value>=0),avg_cost numeric(20,6) NOT NULL DEFAULT 0 CHECK(avg_cost>=0),version integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,warehouse_id,sku_id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),CHECK(on_hand>=reserved+quarantined));
CREATE TABLE stock_movements(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,warehouse_id uuid NOT NULL,sku_id uuid NOT NULL,receipt_id uuid NOT NULL,line_id uuid NOT NULL,qty_base numeric(18,3) NOT NULL,value_vnd numeric(20,0) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,receipt_id,line_id),FOREIGN KEY(tenant_id,receipt_id) REFERENCES receipts(tenant_id,id));
CREATE TABLE sku_projection(tenant_id uuid NOT NULL,sku_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,base_unit text NOT NULL,status text NOT NULL,version integer NOT NULL,PRIMARY KEY(tenant_id,sku_id));
CREATE TABLE idempotency(scope text NOT NULL,key text NOT NULL,body_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor text NOT NULL,action text NOT NULL,entity_id uuid NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX receipts_site ON receipts(tenant_id,site_id,id);
CREATE INDEX movements_sku ON stock_movements(tenant_id,warehouse_id,sku_id);
CREATE INDEX inventory_outbox_pending ON outbox(created_at) WHERE delivered_at IS NULL;
